entries[137638] = { ["name"] = "Überfall", ["text"] = "30 Meter Reichweite\nSofort 45 sek. Abklingzeit\nTeleportiert Euch sofort an die anvisierte Position und hinterlässt einen Schatten Eurer selbst. Nach 10 Sek. oder wenn Ihr den Effekt ein zweites Mal auslöst kehrt Ihr zur Position Eures Schattens zurück." }
entries[137639] = { ["name"] = "Sturm, Erde und Feuer", ["text"] = "10 Energie 40 Meter Reichweite\nSofort\nDer Mönch teilt sich auf und beschwört einen Elementargeist, der sein Ziel angreift. Ein Mönch kann bis zu 2 Elementargeister erschaffen.\n\nDie Geister greifen ihre Ziele an und spiegeln die Schaden verursachenden Angriffe des Mönchs, jedoch wird für jeden beschworenen Geist der Schaden des Mönchs verringert.\n\n1 Geist beschworen - Der Mönch und der Geist verursachen jeweils 70% des normalen Schadens des Mönchs.\n\n2 Geister beschworen - Der Mönch und die Geister verursachen jeweils 55% des normalen Schadens des Mönchs.\n\nDie Elementargeister bleiben bestehen, bis der Mönch den Effekt abbricht oder das Ziel der Geister stirbt oder anderweitig nicht mehr verfügbar ist." }
entries[137641] = { ["name"] = "Seelenfragment", ["text"] = "Sofort\nVon einem Fragment von Gara'jals Seele besessen, das alle 5 Sek. 55000 Schattenschaden verursacht, bis das Seelenfragment an einen anderen Spielercharakter weitergereicht wird. Jeder Tick von 'Seelenfragment' belegt das Ziel mit einem Stapel von 'Verdunkelte Seele'." }
